// One map sprite per class route (docs/00 §5 五阶职业): every stage of a route shares it, so a 圣导师
// still reads as a healer and a 翼神将 as a flier. Mounted branches (弓骑士, 女武神) keep their route's art.
const SPRITES: Record<ClassRoute, [string, string]> = {
  sword: [unitSwordAlly, unitSwordEnemy],
  axe: [unitAxeAlly, unitAxeEnemy],
  armor: [unitArmorAlly, unitArmorEnemy],
  cavalry: [unitCavAlly, unitCavEnemy],
  flying: [unitPegAlly, unitPegEnemy],
  bow: [unitArcherAlly, unitArcherEnemy],
  magic: [unitMageAlly, unitMageEnemy],
  healing: [unitClericAlly, unitClericEnemy],
  stealth: [unitThiefAlly, unitThiefEnemy],
  fist: [unitMonkAlly, unitMonkEnemy],
  beast: [unitBeastAlly, unitBeastEnemy],
  dragon: [unitDragonAlly, unitDragonEnemy],
};
const routeOf = (classId: string): ClassRoute => CLASSES[classId as keyof typeof CLASSES]?.route ?? 'sword';

const PORTRAITS: Record<string, string> = {
  erin: porErin, karl: porKarl, victor: porVictor, lina: porLina, owen: porOwen,
  sera: porSera, noah: porNoah, gustav: porGustav, brock: porBrock,
  ren: porRen, ig: porIg, mira: porMira, roland: porRoland,
};

const WEAPON_ICONS: Record<WeaponType, string> = {
  sword: icoSword, lance: icoLance, axe: icoAxe, bow: icoBow, tome: icoTome, staff: icoStaff,
  fist: icoFist, dagger: icoDagger, beast: icoBeast, dragon: icoDragon,
};

type Looks = Pick<UnitState, 'classId' | 'side'> & { character?: string; portrait?: string; id?: string };

// Map sprites face right for allies and left for enemies.
export function spriteFor(unit: Looks): string {
  return SPRITES[routeOf(unit.classId)][unit.side === 'player' ? 0 : 1];
}

// Named units have hand-made portraits. Everyone else gets a generated one (backend/common/portraits)
// seeded by the unit id, so a unit shows the same face everywhere; clothes follow its class route.
export function portraitFor(unit: Looks): string {
  return PORTRAITS[unit.portrait ?? unit.character ?? unit.id ?? ''] ?? generatedPortrait(unit.id ?? unit.character ?? 'unit', routeOf(unit.classId), unit.side);
}

const generated = new Map<string, string>();
function generatedPortrait(seed: string, route: ClassRoute, side: Looks['side']): string {
  const key = `${seed}|${route}|${side}`;
  let url = generated.get(key);
  if (!url) {
    const canvas = document.createElement('canvas');
    canvas.width = canvas.height = PORTRAIT_SIZE;
    const ctx = canvas.getContext('2d')!;
    const image = ctx.createImageData(PORTRAIT_SIZE, PORTRAIT_SIZE);
    image.data.set(drawPortrait(randomPortrait(seed, { route, side })));
    ctx.putImageData(image, 0, 0);
    url = canvas.toDataURL();
    generated.set(key, url);
  }
  return url;
}

// 交战形象：每个职业手绘一张（backend/common/sprites），手里的武器按本次交战用的武器类型另画一层，
// 肤色发色取角色头像。还没画到的职业返回 null，交战演出退回路线小人。
const battleSprites = new Map<string, string>();
export function battleSpriteFor(unit: Looks, weapon: WeaponType | null): string | null {
  const classId = canonicalClassId(unit.classId as ClassId);
  if (!CLASS_LOOKS[classId]) return null;
  const named = CHARACTER_COLORS[unit.portrait ?? unit.character ?? ''];
  const spec = named ? null : randomPortrait(unit.id ?? unit.character ?? 'unit', { route: routeOf(unit.classId), side: unit.side });
  const colors = { side: unit.side === 'player' ? 'player' as const : 'enemy' as const,
    skin: named?.skin ?? spec!.skin, hair: named?.hair ?? [spec!.hair[0], spec!.hair[2]] as [string, string] };
  const key = `${classId}|${colors.side}|${colors.skin.join()}|${colors.hair.join()}|${weapon}`;
  let url = battleSprites.get(key);
  if (!url) {
    const px = drawBattleSprite(classId, colors, weapon);
    if (!px) return null;
    const canvas = document.createElement('canvas');
    canvas.width = canvas.height = BATTLE_SIZE;
    const ctx = canvas.getContext('2d')!;
    const image = ctx.createImageData(BATTLE_SIZE, BATTLE_SIZE);
    image.data.set(px);
    ctx.putImageData(image, 0, 0);
    url = canvas.toDataURL();
    battleSprites.set(key, url);
  }
  return url;
}

// One icon per weapon type, for class-level displays (转职 options). Single items use itemIconFor.
export function weaponIcon(type: WeaponType): string {
  return WEAPON_ICONS[type];
}

// Every weapon, spellbook, manual and item has its own icon (backend/common/icons), painted once per key.
const itemIcons = new Map<string, string>();
export function itemIconFor(key: string): string {
  let url = itemIcons.get(key);
  if (!url) {
    const px = drawItemIcon(key);
    if (!px) return icoSeal;
    const canvas = document.createElement('canvas');
    canvas.width = canvas.height = ICON_SIZE;
    const ctx = canvas.getContext('2d')!;
    const image = ctx.createImageData(ICON_SIZE, ICON_SIZE);
    image.data.set(px);
    ctx.putImageData(image, 0, 0);
    url = canvas.toDataURL();
    itemIcons.set(key, url);
  }
  return url;
}
